/**
 * Malformed JSON, query or header
 */
export type BadRequestResponse = Problem;

/**
 * Malformed query, cursor, or a cursor used with different filters
 */
export type BadRequestListResponse = Problem;

/**
 * No valid session; sign in again
 */
export type UnauthenticatedResponse = Problem;

/**
 * Missing/invalid CSRF token or cross-origin request
 */
export type ForbiddenResponse = Problem;

/**
 * Unknown resource (also a repeated delete)
 */
export type NotFoundResponse = Problem;

/**
 * The preview expired; start a new reviewed attempt
 */
export type GoneResponse = Problem;

/**
 * The preview expired or its review contents were deleted; upload again
 */
export type GoneImportResponse = Problem;

/**
 * The record changed since it was read; refetch and review
 */
export type PreconditionFailedResponse = Problem;

/**
 * The If-Match header is missing
 */
export type PreconditionRequiredResponse = Problem;

/**
 * A size or row limit was exceeded; nothing was saved
 */
export type PayloadTooLargeResponse = Problem;

/**
 * Wrong content type or unsupported file encoding
 */
export type UnsupportedMediaTypeResponse = Problem;

/**
 * Semantic validation failed; nothing was saved
 */
export type ValidationFailedResponse = Problem;

/**
 * Throttled; wait for Retry-After
 */
export type TooManyRequestsResponse = Problem;

/**
 * Temporarily busy (database lock wait) or in maintenance; bounded retry honoring Retry-After
 */
export type ServiceUnavailableResponse = Problem;

/**
 * Unexpected fault, reported with a safe message and request ID; never a partial result
 */
export type InternalErrorResponse = Problem;

